SELECT EL.APPLY_NO, TO_CHAR(EL.APPLY_TIME, 'DD/MM/YYYY') APPLY_TIME, EL.PERSON_ID, TO_CHAR(EL.LEAVE_FROM_TIME, 'DD/MM/YYYY') FROM_DATE, TO_CHAR(EL.LEAVE_FROM_TIME, 'HH24:MI') FROM_TIME, TO_CHAR(EL.LEAVE_TO_TIME, 'DD/MM/YYYY') TO_DATE, TO_CHAR(EL.LEAVE_TO_TIME, 'HH24:MI') TO_TIME, AR_GET_DAY_HOURS(EL.PERSON_ID, TO_CHAR(EL.LEAVE_FROM_TIME, 'YYYY/MM/DD')) DAY_HOURS, EL.LEAVE_REASON, EL.LEAVE_TYPE_CODE, GET_GLOBAL_NAME(EL.LEAVE_TYPE_CODE, #{lang, jdbcType=VARCHAR}) LEAVE_TYPE_CODE_NAME, EL.APPLY_LENGTH, EL.AFFIRM_FLAG, EL.CONFIRM_FLAG, GET_GLOBAL_NAME(EL.AFFIRM_FLAG, #{lang, jdbcType=VARCHAR}) AFFIRM_FLAG_NAME, HR.EMPID, HR.LOCAL_NAME, HR.DUTY_NO, GET_DEPT_NAME(HR.DEPTNO, #{lang, jdbcType=VARCHAR}) DEPT_NAME, GET_UPDATED_INFO(EL.CREATED_BY) CREATED_BY, GET_GLOBAL_NAME(GET_AR_SHIFTNO(EL.PERSON_ID, TO_CHAR(EL.LEAVE_FROM_TIME, 'YYYY/MM/DD'), EL.CPNY_ID), #{lang, jdbcType=VARCHAR}) SHIFT_NO_NAME, AR_GET_VAC_FOR_ESS(TO_CHAR(EL.LEAVE_FROM_TIME, 'YYYY/MM/DD'), #{cpnyId, jdbcType=VARCHAR}, EL.PERSON_ID, '0') + AR_GET_VAC_FOR_ESS(TO_CHAR(EL.LEAVE_FROM_TIME, 'YYYY/MM/DD'), #{cpnyId, jdbcType=VARCHAR}, EL.PERSON_ID, '4') + AR_GET_VAC_FOR_ESS(TO_CHAR(EL.LEAVE_FROM_TIME, 'YYYY/MM/DD'), #{cpnyId, jdbcType=VARCHAR}, EL.PERSON_ID, 'LAST_YEAR_VAC') TOT_VAC_CNT, AR_GET_VAC_FOR_ESS(TO_CHAR(EL.LEAVE_FROM_TIME, 'YYYY/MM/DD'), #{cpnyId, jdbcType=VARCHAR}, EL.PERSON_ID, '3') SHENGYU_VAC_CNT, HPI.SEXCODE FROM ESS_LEAVE_APPLY_TB EL JOIN HR_EMPLOYEE HR ON HR.PERSON_ID = EL.PERSON_ID LEFT JOIN HR_PERSONAL_INFO HPI ON HPI.PERSON_ID = EL.PERSON_ID WHERE EL.CPNY_ID = #{cpnyId, jdbcType=VARCHAR} AND EL.ACTIVITY = '1' AND NVL(EL.BATCH_YN, '1') <> '2' AND EL.PERSON_ID NOT LIKE '111111%' AND EXISTS ( SELECT B1.DEPTID FROM HR_DEPARTMENT B1 WHERE B1.DEPTNO = HR.DEPTNO START WITH B1.DEPTNO IN ( SELECT HRD.DEPTID FROM HR_DEPARTMENT HRD WHERE HRD.MANAGER_EMP_ID = #{adminID, jdbcType=VARCHAR} ) CONNECT BY PRIOR B1.DEPTNO = B1.PARENT_DEPT_NO UNION SELECT AR_SUPERVISOR_INFO.DEPTNO FROM AR_SUPERVISOR_INFO WHERE AR_SUPERVISOR_INFO.DEPTNO = HR.DEPTNO AND AR_SUPERVISOR_INFO.PERSON_ID = #{adminID, jdbcType=VARCHAR} )
AND EXISTS ( SELECT 1 FROM HR_DEPARTMENT D WHERE D.DEPTNO = HR.DEPTNO AND D.ACTIVITY = 1 START WITH D.DEPTNO = #{deptNo, jdbcType=VARCHAR} CONNECT BY PRIOR D.DEPTNO = D.PARENT_DEPT_NO )
AND HR.SHIFT_NO = #{shiftNo, jdbcType=VARCHAR}
AND ( UPPER(HR.EMPID) LIKE '%' || UPPER(#{keyword, jdbcType=VARCHAR}) || '%' OR CONVERTTOUNSIGN(UPPER(HR.LOCAL_NAME)) LIKE '%' || CONVERTTOUNSIGN(UPPER(#{keyword, jdbcType=VARCHAR})) || '%' OR UPPER(HR.CHINESE_PINYIN) LIKE '%' || UPPER(#{keyword, jdbcType=VARCHAR}) || '%' )
AND EL.LEAVE_TYPE_CODE = #{searchLeaveTypeCode, jdbcType=VARCHAR}
AND EL.AFFIRM_FLAG = #{searchAffirmFlag, jdbcType=VARCHAR}
AND EL.CONFIRM_FLAG = #{searchConfirmFlag, jdbcType=VARCHAR}
AND ( (TRUNC(EL.LEAVE_FROM_TIME) >= TO_DATE(#{startDate, jdbcType=VARCHAR}, 'YYYY-MM-DD') AND TRUNC(EL.LEAVE_FROM_TIME) <= TO_DATE(#{endDate, jdbcType=VARCHAR}, 'YYYY-MM-DD')) OR (TRUNC(EL.LEAVE_FROM_TIME) <= TO_DATE(#{startDate, jdbcType=VARCHAR}, 'YYYY-MM-DD') AND TRUNC(EL.LEAVE_TO_TIME) >= TO_DATE(#{endDate, jdbcType=VARCHAR}, 'YYYY-MM-DD')) OR (TRUNC(EL.LEAVE_TO_TIME) >= TO_DATE(#{startDate, jdbcType=VARCHAR}, 'YYYY-MM-DD') AND TRUNC(EL.LEAVE_TO_TIME) <= TO_DATE(#{endDate, jdbcType=VARCHAR}, 'YYYY-MM-DD')) )
ORDER BY EL.APPLY_TIME DESC

SELECT TO_CHAR(A.APPLY_NO) APPLY_NO, A.AFFIRM_TYPE, A.AFFIRM_LEVEL, A.AFFIRM_PERSON_ID, HR.EMPID, HR.LOCAL_NAME, GET_DEPT_NAME(HR.DEPTNO, #{lang, jdbcType=VARCHAR}) DEPTNAME, GET_GLOBAL_NAME(HR.POSITION_NO, #{lang, jdbcType=VARCHAR}) POSITION_NAME FROM SY_AFFIRM_EMAIL A JOIN HR_EMPLOYEE HR ON HR.PERSON_ID = A.AFFIRM_PERSON_ID WHERE A.AFFIRM_TYPE <> '4' AND TO_CHAR(A.APPLY_NO) IN
#{no, jdbcType=VARCHAR}
ORDER BY A.APPLY_NO, TO_NUMBER(A.AFFIRM_LEVEL)

SELECT TB.MISDOCID
  FROM ESS_LEAVE_APPLY_TB TB
 WHERE TB.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
   AND TB.SEND_EMAIL_FLAG = 1
   AND TB.APPLY_NO = #{applyNo, jdbcType=VARCHAR}

