UPDATE ESS_LEAVE_APPLY_TB
   SET ACTIVITY = 0,
       UPDATE_DATE = SYSDATE,
       UPDATED_BY = #{adminID, jdbcType=VARCHAR},
       UPDATED_IP = #{adminIP, jdbcType=VARCHAR}
 WHERE APPLY_NO = #{applyNo, jdbcType=VARCHAR}
